// Подвал поста собираем кодом: тег рубрики + теги темы + ссылка на Instagram. Модель даёт только
// теги темы последней строкой; ссылку ей не доверяем — она её перевирает.
const IG_URL = 'https://www.instagram.com/fitness_fox_bot';
const RUBRIC_TAGS = { check: '#рыж_проверяет', price: '#почём_белок', recipe: '#рецепт_рыжа', guess: '#на_глаз', swap: '#вместо_этого', tried: '#рыж_пробует', fox: '#лис' };
const FOOTER_RE = /\n*(?:#[^\n]*\n)?📸 <a href="https:\/\/www\.instagram\.com[^\n]*\s*$/;
function splitTags(text) {
  const lines = String(text).trim().split('\n');
  const last = (lines[lines.length - 1] || '').trim();
  if (!/^(#[\p{L}\p{N}_]+[\s,]*)+$/u.test(last)) return { text: String(text).trim(), tags: [] };
  lines.pop();
  return { text: lines.join('\n').trim(), tags: last.match(/#[\p{L}\p{N}_]+/gu).map(t => t.toLowerCase()) };
}
function withFooter(text, rubric, tags) {
  const all = [...new Set([RUBRIC_TAGS[rubric], ...tags].filter(Boolean))].slice(0, 3);
  return `${text}\n\n${all.join(' ')}\n📸 <a href="${IG_URL}">Рыж в Instagram</a>`;
}

// openAi v2.3 отдаёт Responses-формат: { output:[{ content:[{ text }] }] }.
// Запасные пути — под другие версии ноды.
function extractText(j) {
  if (Array.isArray(j.output)) {
    for (const o of j.output) {
      const part = Array.isArray(o.content) && o.content.find(c => c.text);
      if (part?.text) return part.text;
    }
  }
  if (Array.isArray(j.content)) {
    const part = j.content.find(c => c.text);
    if (part?.text) return part.text;
  }
  return j.message?.content ?? j.content ?? j.text ?? '';
}
const raw = String(extractText($input.first().json) || '').trim();
// Срезаем markdown-фенсы, если модель их всё-таки поставила.
const clean = raw.replace(/^```(?:html)?\s*/i, '').replace(/```\s*$/, '').trim();
if (!clean) throw new Error('LLM вернул пустой текст');
const { text, tags } = splitTags(clean.replace(FOOTER_RE, ''));
const body = withFooter(text, $('Topic').first().json.rubric, tags);
// len — как его посчитает Telegram (без разметки); по нему решаем, сокращать ли.
const len = body.replace(/<[^>]+>/g, '').length;
return [{ json: { body, text, tags, len } }];

