// Рыжа рисуем ОТ ЭТАЛОНА (спрайт fox_m2_b0 из Mini App, подаётся картинкой в Generate Ryzh):
// по одному текстовому описанию модель каждый раз рисует «какого-то лиса». LLM даёт только сцену.
function extractText(j) {
  if (Array.isArray(j.output)) {
    for (const o of j.output) {
      const part = Array.isArray(o.content) && o.content.find(c => c.text);
      if (part?.text) return part.text;
    }
  }
  return j.message?.content ?? j.content ?? j.text ?? '';
}
const scene = String(extractText($input.first().json) || '').trim().replace(/^["']|["']$/g, '');
const prompt = [
  'The reference image shows Ryzh, our mascot. Draw the SAME character: identical head, face and eyes,',
  'the same muscular athletic build with broad shoulders, defined chest and six-pack abs,',
  'orange headband, orange wristbands, black sports shorts with an orange side stripe,',
  'orange fur #E8763A with cream muzzle, chest and belly, fluffy tail with white tip, the same thick black outlines.',
  `New scene: ${scene || 'standing confidently, paws on hips, cheerful smile'}.`,
  'Full body, centered. Flat vector mascot illustration, thick clean black outlines, soft cel shading,',
  'vibrant, solid flat dark background #0D0C13 with nothing else on it, no floor, mobile app sticker,',
  'expressive, no text, no letters, square 1:1.',
].join(' ');
return [{ json: { prompt, scene } }];

// Тема для черновика приходит по id из Control (редактор выбрал её в меню).
// cta — призыв поставить реакцию: примерно каждый третий день (каждый пост — надоест).
// Решение по дню, а не случайно: темы, взятые в один день, ведут себя одинаково.
const day = Math.floor(Date.now() / 86400000);
return $input.all().map(i => ({ json: { ...i.json, cta: day % 3 === 0 } }));

const RUBRICS = { check: 'Рыж проверяет', price: 'Почём белок', recipe: 'Рецепт Рыжа', guess: 'На глаз', swap: 'Вместо этого', tried: 'Рыж пробует', fox: 'Лис' };
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const plain = s => String(s ?? '').replace(/<[^>]+>/g, '').replace(/&(lt|gt|amp|quot);/g, '_');
function buildCaption(c) {
  const head = `<b>#${c.post_id}</b> · ${esc(RUBRICS[c.rubric] || c.rubric || '—')} · v${c.version}\n<i>${esc(c.title)}</i>\n\n`;
  const len = plain(c.body).length;
  const full = head + c.body;
  if (plain(full).length <= 1024) return { caption: full, full, fits: true, len };
  const note = `<b>#${c.post_id}</b> ⚠️ ${len} зн. — длиннее подписи (1024). Ответь «сократи до 800».\n\n`;
  return { caption: note + esc(plain(c.body).slice(0, 850)) + '…', full: note + full, fits: false, len };
}

// Новый черновик приходит после Save Draft и идёт редакторам текстом, без затрат на картинку.
// Вызов с post_id (кнопка 🎨) — после Load Post, там есть body: рисуем картинку.
const inp = $input.first().json;
let c;
if (inp.version !== undefined) {
  c = { post_id: inp.id, title: inp.title, rubric: inp.rubric, body: inp.body,
        version: inp.version, old_post_id: inp.old_post_id, step: 'image' };
} else {
  const t = $('Topic').first().json;
  c = { post_id: $('Save Draft').first().json.id, title: t.title, rubric: t.rubric,
        body: $('Save Draft').first().json.body, version: 1, old_post_id: null, step: 'text' };
}
return [{ json: { ...c, ...buildCaption(c) } }];

